from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    stack = []
    i = 0
    while i < len(paren_string):
        if paren_string[i] == '(':
            stack.append(i)
        elif paren_string[i] == ')':
            if stack:
                stack.pop()
                start = stack[-1] + 1 if stack else 0
                if start < i:
                    groups.append(paren_string[start:i + 1])
            else:
                i += 1
                continue
        i += 1
    return groups

